const handleFilterChange = () => {
  // 搜索关键词做首尾去空格，避免只输入空格也当作有效搜索词
  searchKeyword.value = searchKeyword.value.trim()
}

// 把 "20-40k" / "18k" / "面议" 这类字符串解析成 { min, max }（单位: K）
const parseSalaryRange = (salaryStr) => {
  if (!salaryStr || salaryStr.includes('面议')) return null

  const nums = salaryStr.match(/\d+(\.\d+)?/g)
  if (!nums || nums.length === 0) return null

  const values = nums.map(Number)
  const min = values[0]
  const max = values.length > 1 ? values[1] : values[0]
  return { min, max }
}

// 判断某个岗位的薪资是否命中选中的区间桶
const matchSalaryBucket = (job, bucket) => {
  if (bucket === 'all') return true
  if (bucket === 'negotiate') {
    return job.salaryTag === 'negotiate' || (job.salary || '').includes('面议')
  }

  const range = parseSalaryRange(job.salary)
  if (!range) return false
  const { min, max } = range

  switch (bucket) {
    case '15k-below':
      return min < 15
    case '15k-20k':
      return max >= 15 && min <= 20
    case '20k-25k':
      return max >= 20 && min <= 25
    case '25k-35k':
      return max >= 25 && min <= 35
    case '35k-up':
      return max > 35
    default:
      return true
  }
}

// 弹窗打开关闭
const openDetail = (job) => {
  currentJob.value = { ...job }
  showModal.value = true
}
const closeDetail = () => {
  showModal.value = false
  currentJob.value = {}
}

// 搜索 +薪资 +工作模式过滤（不含左侧职能分类），供 displayJobs 和 familyCounts 共用
const searchSalaryModeFiltered = computed(() => {
  const kw = searchKeyword.value.trim().toLowerCase()
  return originJobs.value.filter(job => {
    // 岗位名称搜索
    if (kw && !job.title.toLowerCase().includes(kw)) {
      return false
    }
    // 薪资
    if (!matchSalaryBucket(job, salaryVal.value)) {
      return false
    }
    // 工作模式
    if (workModeVal.value === 'remote' && !job.remote) return false
    if (workModeVal.value === 'onsite' && !job.onsite) return false

    return true
  })
})

// 全部过滤逻辑：分类 +搜索 +薪资 +工作模式
const displayJobs = computed(() => {
  return searchSalaryModeFiltered.value.filter(job => {
    // 左侧职能分类过滤
    if (currentFamily.value !== 'all' && job.familyKey !== currentFamily.value) {
      return false
    }
    return true
  })
})

// 每个左侧分类当前实际匹配到的岗位数（跟随搜索/薪资/工作模式实时变化）
const familyCounts = computed(() => {
  const counts = {}
  familyList.value.forEach(item => {
    counts[item.key] = item.key === 'all'
      ? searchSalaryModeFiltered.value.length
      : searchSalaryModeFiltered.value.filter(job => job.familyKey === item.key).length
  })
  return counts
})
/* ==================== 分页 ==================== */
const PAGE_SIZE = 12          // 每页条数，可按需调整
const currentPage = ref(1)
const jumpPage = ref('')

// 总页数
const totalPages = computed(() => {
  return Math.max(1, Math.ceil(displayJobs.value.length / PAGE_SIZE))
})

// 当前页数据（只渲染这些，避免一次性渲染全部卡片）
const paginatedJobs = computed(() => {
  const start = (currentPage.value - 1) * PAGE_SIZE
  return displayJobs.value.slice(start, start + PAGE_SIZE)
})

// 页码按钮（最多显示 5 个，当前页居中）
const pageNumbers = computed(() => {
  const total = totalPages.value
  const cur = currentPage.value
  const maxShow = 5
  if (total <= maxShow) {
    return Array.from({ length: total }, (_, i) => i + 1)
  }
  let start = Math.max(1, cur - Math.floor(maxShow / 2))
  let end = start + maxShow - 1
  if (end > total) {
    end = total
    start = end - maxShow + 1
  }
  return Array.from({ length: end - start + 1 }, (_, i) => start + i)
})

// 跳转（含边界处理）
const goToPage = (p) => {
  const target = Math.min(Math.max(1, Number(p) || 1), totalPages.value)
  if (target === currentPage.value) return
  currentPage.value = target
  scrollToJobsTop()
}

const handleJump = () => {
  const p = Number(jumpPage.value)
  if (!p || p < 1 || p > totalPages.value) {
    jumpPage.value = ''
    return
  }
  goToPage(p)
  jumpPage.value = ''
}

// 翻页后滚回岗位区域顶部
const scrollToJobsTop = () => {
  const el = document.getElementById('Jobs')
  if (!el) return
  const headerHeight = 80
  const top = el.offsetTop - headerHeight
  window.scrollTo({ top, behavior: 'smooth' })
}

// 筛选/分类变化 → 回到第 1 页
watch([searchKeyword, salaryVal, workModeVal, currentFamily], () => {
  currentPage.value = 1
})

// 数据总量变化导致当前页越界时，自动回退到最后一页
watch(totalPages, (t) => {
  if (currentPage.value > t) currentPage.value = t
})
</script>

